UPDATE categories SET h1_en = 'Electronics', seo_title_sr = 'Elektronika: telefoni, računari, televizori', seo_title_en = 'Electronics: phones, computers, TVs', meta_sr = 'Elektronika: mobilni telefoni, laptopovi, konzole, televizori, slušalice i foto oprema. {count} sa cenama i fotografijama. Besplatno na Place4Market.', meta_en = 'Electronics: mobile phones, laptops, consoles, TVs, headphones and cameras. {count} with prices and photos. Buy or sell for free on Place4Market.', text_sr = 'Elektronika obuhvata mobilne telefone i opremu, laptopove i računare, komponente, konzole i igrice, televizore, slušalice i zvučnike, foto opremu i pametne satove. Većina ponuda su polovni uređaji po povoljnijim cenama, ali ima i novih u originalnom pakovanju.

Kod kupovine polovne elektronike proverite da li uređaj radi, stanje baterije i ekrana i da li ide uz račun ili garanciju. Prodavci dobijaju više upita kada navedu model, memoriju i stanje i dodaju fotografije uređaja.', text_en = 'Electronics covers mobile phones and accessories, laptops and desktops, components, consoles and games, TVs, headphones and speakers, cameras and smartwatches. Most offers are used devices at lower prices, but there are new ones in original packaging too.

When buying used electronics, check that the device works, the state of the battery and screen, and whether it comes with a receipt or warranty. Sellers get more replies when they give the model, storage and condition and add photos of the device.' WHERE slug = 'electronics';
UPDATE categories SET h1_en = 'Mobile phones', seo_title_sr = 'Mobilni telefoni: novi i polovni, cene', seo_title_en = 'Mobile phones: new and used, prices', meta_sr = 'Mobilni telefoni: Xiaomi, iPhone, Samsung, Huawei i Honor, Nokia. {count} sa cenama i fotografijama. Kupite ili prodajte besplatno na Place4Market.', meta_en = 'Mobile phones: Xiaomi, iPhone, Samsung, Huawei and Honor, Nokia. {count} with prices and photos. Buy or sell for free on Place4Market.', text_sr = 'Mobilni telefoni, novi i polovni: Xiaomi, iPhone, Samsung, Huawei i Honor, Nokia i drugi modeli. Filter po marki i gradu brzo vodi do ponuda u vašoj blizini.

Pre kupovine proverite da li je telefon otključan za sve mreže, stanje baterije i ekrana i da li je odjavljen sa naloga (iCloud ili Google). Prodavci neka navedu model, memoriju, stanje i da li ide uz punjač i račun.', text_en = 'Mobile phones, new and used: Xiaomi, iPhone, Samsung, Huawei and Honor, Nokia and other models. The make and city filters quickly lead you to offers near you.

Before buying, check that the phone is unlocked for all networks, the battery and screen condition, and that it is signed out of its account (iCloud or Google). Sellers should state the model, storage, condition and whether a charger and receipt are included.' WHERE slug = 'phones';
UPDATE categories SET h1_en = 'Consoles and video games', seo_title_sr = 'Konzole i igrice: PlayStation, Nintendo', seo_title_en = 'Consoles and games: PlayStation, Nintendo', meta_sr = 'Konzole i video igre: PlayStation 5 i 4, Nintendo Switch, Xbox, igrice i džojstici. {count} sa cenama i fotografijama. Besplatno na Place4Market.', meta_en = 'Consoles and video games: PlayStation 5 and 4, Nintendo Switch, Xbox, games and controllers. {count} with prices and photos. Free on Place4Market.', text_sr = 'Konzole i video igre: PlayStation 5 i 4, Nintendo Switch, Xbox, igrice, džojstici i oprema. Polovne konzole i igrice su mnogo povoljnije od novih.

Proverite da li konzola radi bez pregrevanja i buke, da li džojstici rade ispravno i da li je nalog odjavljen. Prodavci neka navedu model, memoriju i šta ide uz konzolu.', text_en = 'Consoles and video games: PlayStation 5 and 4, Nintendo Switch, Xbox, games, controllers and accessories. Used consoles and games cost much less than new ones.

